mapper.select:
select p.product_id as value, p.product_name as label, p.product_code as code, concat_ws(' · ', p.product_code, p.spec, p.unit) as meta, p.status as status, 'product' as type from inv_product p where p.del_flag = '0' and p.status = '0'
and ( p.product_name like concat('%', #{keyword}, '%') or p.product_code like concat('%', #{keyword}, '%') or p.sku like concat('%', #{keyword}, '%') )
order by p.product_name asc, p.product_id desc limit #{limit}

select c.customer_id as value, c.customer_name as label, c.customer_code as code, concat_ws(' · ', c.customer_code, c.contact_person, c.contact_phone) as meta, c.status as status, 'customer' as type from inv_customer c where c.status = '0'
and ( c.customer_name like concat('%', #{keyword}, '%') or c.customer_code like concat('%', #{keyword}, '%') or c.contact_phone like concat('%', #{keyword}, '%') )
order by c.customer_name asc, c.customer_id desc limit #{limit}

select s.supplier_id as value, s.supplier_name as label, s.supplier_code as code, concat_ws(' · ', s.supplier_code, s.contact_person, s.contact_phone) as meta, s.status as status, 'supplier' as type from inv_supplier s where s.status = '0' and (s.cooperation_status is null or s.cooperation_status = '0')
and ( s.supplier_name like concat('%', #{keyword}, '%') or s.supplier_code like concat('%', #{keyword}, '%') or s.contact_phone like concat('%', #{keyword}, '%') )
order by s.supplier_name asc, s.supplier_id desc limit #{limit}

